import * as http from 'http';
import * as crypto from 'crypto';
import * as fs from 'fs';
import * as path from 'path';

const STORAGE_ROOT = '/var/proxy-cache';
const ENCRYPTION_KEY = crypto.randomBytes(32);
const IV_LENGTH = 16;

interface CacheEntry {
  url: string;
  timestamp: number;
  headers: Record<string, string>;
}

function encrypt(data: Buffer): Buffer {
  const iv = crypto.randomBytes(IV_LENGTH);
  const cipher = crypto.createCipheriv('aes-256-cbc', ENCRYPTION_KEY, iv);
  const encrypted = Buffer.concat([iv, cipher.update(data), cipher.final()]);
  return encrypted;
}

function decrypt(data: Buffer): Buffer {
  const iv = data.slice(0, IV_LENGTH);
  const decipher = crypto.createDecipheriv('aes-256-cbc', ENCRYPTION_KEY, iv);
  return Buffer.concat([decipher.update(data.slice(IV_LENGTH)), decipher.final()]);
}

function normalizeUrlToPath(urlStr: string): string {
  const parsed = new URL(urlStr);
  const hostDir = parsed.hostname.replace(/[^a-zA-Z0-9.-]/g, '_');
  const pathSegments = parsed.pathname.split('/').filter(s => s.length > 0);
  const sanitizedSegments = pathSegments.map(seg => {
    return seg.replace(/[^a-zA-Z0-9._-]/g, '_');
  });
  return path.join(hostDir, ...sanitizedSegments);
}

function computeCacheKey(method: string, url: string, vary: Record<string, string>): string {
  const hash = crypto.createHash('sha256');
  hash.update(method);
  hash.update(url);
  hash.update(JSON.stringify(vary));
  return hash.digest('hex');
}

function resolveCachePath(cacheKey: string, urlPath: string): string {
  const baseDir = path.resolve(STORAGE_ROOT, urlPath);
  const filePath = path.join(baseDir, cacheKey + '.enc');
  return filePath;
}

function validateStoragePath(resolvedPath: string): boolean {
  const normalized = path.normalize(resolvedPath);
  return normalized.startsWith(path.resolve(STORAGE_ROOT));
}

async function storeResponse(url: string, method: string, headers: Record<string, string>, body: Buffer): Promise<void> {
  const urlPath = normalizeUrlToPath(url);
  const cacheKey = computeCacheKey(method, url, {});
  const cachePath = resolveCachePath(cacheKey, urlPath);

  if (!validateStoragePath(cachePath)) {
    throw new Error('Invalid cache path detected');
  }

  const entry: CacheEntry = { url, timestamp: Date.now(), headers };
  const metadata = Buffer.from(JSON.stringify(entry));
  const metaLength = Buffer.alloc(4);
  metaLength.writeUInt32BE(metadata.length, 0);

  const payload = Buffer.concat([metaLength, metadata, body]);
  const encrypted = encrypt(payload);

  await fs.promises.mkdir(path.dirname(cachePath), { recursive: true });
  await fs.promises.writeFile(cachePath, encrypted);
}

async function retrieveResponse(url: string, method: string): Promise<{ headers: Record<string, string>; body: Buffer } | null> {
  const urlPath = normalizeUrlToPath(url);
  const cacheKey = computeCacheKey(method, url, {});
  const cachePath = resolveCachePath(cacheKey, urlPath);

  if (!validateStoragePath(cachePath)) {
    return null;
  }

  try {
    const encrypted = await fs.promises.readFile(cachePath);
    const payload = decrypt(encrypted);
    const metaLength = payload.readUInt32BE(0);
    const metadata: CacheEntry = JSON.parse(payload.slice(4, 4 + metaLength).toString());
    const body = payload.slice(4 + metaLength);
    return { headers: metadata.headers, body };
  } catch {
    return null;
  }
}

function handlePurgeRequest(req: http.IncomingMessage, res: http.ServerResponse): void {
  let body = '';
  req.on('data', chunk => body += chunk);
  req.on('end', async () => {
    try {
      const { pattern } = JSON.parse(body);
      const decodedPattern = decodeURIComponent(pattern);
      const targetDir = path.join(STORAGE_ROOT, decodedPattern);

      if (!targetDir.startsWith(STORAGE_ROOT)) {
        res.writeHead(403);
        res.end('Forbidden');
        return;
      }

      await fs.promises.rm(targetDir, { recursive: true, force: true });
      res.writeHead(200);
      res.end('Purged');
    } catch (e) {
      res.writeHead(400);
      res.end('Bad request');
    }
  });
}

const server = http.createServer(async (req, res) => {
  if (req.method === 'PURGE') {
    handlePurgeRequest(req, res);
    return;
  }

  const targetUrl = req.headers['x-proxy-target'] as string;
  if (!targetUrl) {
    res.writeHead(400);
    res.end('Missing target');
    return;
  }

  const cached = await retrieveResponse(targetUrl, req.method || 'GET');
  if (cached) {
    Object.entries(cached.headers).forEach(([k, v]) => res.setHeader(k, v));
    res.writeHead(200);
    res.end(cached.body);
    return;
  }

  res.writeHead(502);
  res.end('Upstream fetch not implemented in this example');
});

server.listen(8080);
